; Reads the keyboard once a pass of the main loop. F1 set-up and players, F7 start, F3 music or effects, F5 pause, CTRL+V version, Q quit. A joystick in port 1 acts as keys: left is CTRL, right is F7, fire is F1.
read_keys
        lda #$ff
        sta CIADDRA                     ; Port A drives the key rows, port B reads the key columns.
        lda #$00
        sta CIADDRB
        lda #$7f                        ; Row 7: bit 2 is CTRL.
        sta CIAPRA
        lda CIAPRB
        and #$04
        bne read_keys_check_f1
        lda #$f7                        ; Row 3: bit 7 is V.
        sta CIAPRA
        lda CIAPRB
        and #$80
        bne read_keys_check_f1
        lda #$80                        ; Not in build V 05 05 87: stops the sprites while the version text shows.
        sta sprites_frozen
; Shows text $81 ("V 05 10 87") while CTRL and V stay pressed.
read_keys_show_version
