        jsr print_text
        lda CIAPRB
        and #$80
        beq read_keys_show_version
        lda #$00                        ; Not in build V 05 05 87: lets the sprites move again.
        sta sprites_frozen
        jsr reset_fight_colours         ; Removes the text from the screen when V is released.
read_keys_check_f1
        lda #$fe                        ; Row 0: bit 4 is F1.
        sta CIAPRA
        lda CIAPRB
        and #$10
        bne read_keys_check_f3
        lda setup_active                ; During set-up, in a started game, during a turn or after a fighter died, F1 does not start the set-up. In the demo, F1 then still toggles the players.
        ora game_started
        ora turn_request
        ora bout_loser
        bmi read_keys_f1_clock
        lda #$80                        ; Starts the set-up: opponent 0, demo off.
        sta setup_active
        lda #$00
        sta opponent_index
        sta game_started
        sta demo_mode
        lda scene_index                 ; Goes back to scene 0 when scene 1 shows.
        beq read_keys_f1_reset
; not executed $929a-$929c
        jsr change_scene
read_keys_f1_reset
        jsr init_fighters               ; Resets the fighters and the sprite tables.
        jsr reset_sprite_scripts
        lda sprite_mirror_state         ; Mirrors the fighter sprites back when they are mirrored.
        beq read_keys_f1_clock
; not executed $92a7-$92ad
        eor #$81
        sta sprite_mirror_state
        jsr mirror_shared_sprites
read_keys_f1_clock
        lda game_started                ; Before F7, F1 also resets the bout clock and changes the number of players.
        bmi read_keys_check_f3
        jsr reset_timer
        lda two_players                 ; Part 1 only: toggles two_players between 0 (1PLR) and 1 (2PLR). Part 2 sets two_players to 0 here.
        eor #$01
        sta two_players
read_keys_check_f3
        lda #$fe                        ; Row 0: bit 5 is F3.
        sta CIAPRA
        lda CIAPRB
        and #$20
        bne read_keys_check_f5
        jsr stop_sound                  ; Fades out and stops the sound before the change.
        lda sound_off                   ; Toggles bit 7 of sound_off: music mode or sound effects mode.
        eor #$80
        sta sound_off
        bpl read_keys_f3_fade_in
        lda #$80                        ; Music mode: requests tunes $80-$82 on the three voices.
        sta sound_request
        lda #$81
        sta sound_request+1
        lda #$82
        sta sound_request+2
read_keys_f3_fade_in
        lda #$81                        ; Starts a fade-in of the volume.
        sta fade_in_request
read_keys_check_f5
        lda #$fe                        ; Row 0: bit 6 is F5.
        sta CIAPRA
        lda CIAPRB
        and #$40
        bne read_keys_check_f7
        lda setup_active                ; F5 has no effect during the set-up.
        bmi read_keys_check_q
        lda #$80                        ; Not in build V 05 05 87. That build stores 0, and the sprites do not stop.
        sta sprites_frozen              ; Sets sprites_frozen to $80. Thus the sprites stop during the pause.
        jsr busy_wait                   ; Waits, so that the player can release F5.
read_keys_pause_wait
