        and #$40
        bne read_keys_pause_wait
        sta sprites_frozen
        jsr reset_fight_colours         ; Clears the text area of the screen.
read_keys_check_f7
        lda #$fe                        ; Row 0: bit 3 is F7.
        sta CIAPRA
        lda CIAPRB
        and #$08
        bne read_keys_check_q
        lda setup_active                ; F7 works only during the set-up.
        bpl read_keys_check_q
        sta game_started                ; Starts the game: game_started gets $80, the set-up ends, the bout clock resets.
        lda #$00
